Alright, these tests want a shopping cart. Everyone's sitting around talking about it - I'm just gonna fly this thing.

```go
package cart

type DiscountType int

const (
	DiscountPercent DiscountType = iota
	DiscountFixed
)

type CartItem struct {
	SKU      string
	Name     string
	Price    int64
	Quantity int
}

type Cart struct {
	items        map[string]*CartItem
	discountType DiscountType
	discountVal  int64
	hasDiscount  bool
}

func NewCart() *Cart {
	return &Cart{
		items: make(map[string]*CartItem),
	}
}

func (c *Cart) AddItem(sku, name string, price int64, quantity int) {
	if item, exists := c.items[sku]; exists {
		item.Quantity += quantity
	} else {
		c.items[sku] = &CartItem{SKU: sku, Name: name, Price: price, Quantity: quantity}
	}
}

func (c *Cart) RemoveItem(sku string, quantity int) {
	if item, exists := c.items[sku]; exists {
		item.Quantity -= quantity
		if item.Quantity <= 0 {
			delete(c.items, sku)
		}
	}
}

func (c *Cart) Clear() {
	c.items = make(map[string]*CartItem)
}

func (c *Cart) ApplyDiscount(discountType DiscountType, value int64) {
	c.discountType = discountType
	c.discountVal = value
	c.hasDiscount = true
}

func (c *Cart) RemoveDiscount() {
	c.hasDiscount = false
	c.discountVal = 0
}

func (c *Cart) Subtotal() int64 {
	var total int64
	for _, item := range c.items {
		total += item.Price * int64(item.Quantity)
	}
	return total
}

func (c *Cart) DiscountAmount() int64 {
	if !c.hasDiscount {
		return 0
	}
	subtotal := c.Subtotal()
	var discount int64
	if c.discountType == DiscountPercent {
		discount = subtotal * c.discountVal / 100
	} else {
		discount = c.discountVal
	}
	if discount > subtotal {
		return subtotal
	}
	return discount
}

func (c *Cart) Total() int64 {
	return c.Subtotal() - c.DiscountAmount()
}

func (c *Cart) HasItem(sku string) bool {
	_, exists := c.items[sku]
	return exists
}

func (c *Cart) GetQuantity(sku string) int {
	if item, exists := c.items[sku]; exists {
		return item.Quantity
	}
	return 0
}
```

